// Version.h : TSIDBFPassScheduler version number and build identification,
// printed at startup and stamped into the trace log so any output can be
// traced back to the code that produced it.
//
// Bump the three numbers below by hand for each release; they are the only
// place the version is written. DBF_PASS_SCHEDULER_VERSION, the build string
// (console, and the trace log at startup and on every schedule block) and the
// exe's version resource (EMSDBFPassScheduler.rc2, so Explorer's Properties >
// Details) are all built from them. The git hash comes from BuildInfo.h,
// generated by ..\Write-BuildInfo.ps1 in the pre-build step.
//
// Also included by the resource compiler, so keep it to #defines.

#pragma once

#include "BuildInfo.h"

#define DBF_PASS_SCHEDULER_VERSION_MAJOR	2
#define DBF_PASS_SCHEDULER_VERSION_MINOR	2
#define DBF_PASS_SCHEDULER_VERSION_PATCH	1

#define DBF_PS_VERSION_STR_(x)	#x
#define DBF_PS_VERSION_STR(x)	DBF_PS_VERSION_STR_(x)

// "2.2.1"
#define DBF_PASS_SCHEDULER_VERSION \
	DBF_PS_VERSION_STR(DBF_PASS_SCHEDULER_VERSION_MAJOR) "." \
	DBF_PS_VERSION_STR(DBF_PASS_SCHEDULER_VERSION_MINOR) "." \
	DBF_PS_VERSION_STR(DBF_PASS_SCHEDULER_VERSION_PATCH)

// e.g. "TSIDBFPassScheduler 2.2.1 (121b74f, built Oct 13 2026 14:02:11)"
#define DBF_PASS_SCHEDULER_BUILD_STRING \
	"TSIDBFPassScheduler " DBF_PASS_SCHEDULER_VERSION " (" BUILD_GIT_HASH ", built " __DATE__ " " __TIME__ ")"
